/**
 * [PH11.1] صياغة تعليمات الاستعمال للوليّ أمر — BRD §9.
 *
 * ── الحدّ الذي لا يُتجاوز ─────────────────────────────────────────────────────
 * **النموذج لا يختار جرعة، ولا طريقًا، ولا تواترًا، ولا مدّة.** كلّها تصل إليه
 * محسوبةً من محرّك الجرعة (§5) واختيار المدرّب، ومهمّته **إعادة صياغتها بلغة يفهمها
 * وليّ الأمر** — لا أكثر. هذا هو الفرق بين مساعد تحرير ومصدر سريري، و§0.4 يمنع الثاني
 * منعًا باتًّا: «جرعة ملفَّقة في نظام سريري حادثةُ سلامة طفل».
 *
 * ولذلك تُمرَّر الأرقام في المُدخَل ويُطلب في التوجيه أن تُنقل حرفيًّا؛ وإن نقص رقمٌ
 * منها لا يُطلب من النموذج سدّه، بل يُعطَّل الزرّ في الواجهة ويُقال ما ينقص.
 *
 * النصّ الناتج **اقتراح قابل للتحرير** يملأ حقلًا يملكه المدرّب، لا شيء يُحفظ خلفه.
 */
export type DraftSigInput = {
    drugName: string;
    /** الجرعة كما حسبها المحرّك — تُنقل كما هي */
    doseText: string | null;
    /** ما يُقاس فعلًا (مثل «0.5 mL») — أوضح للوليّ أمر من الملّيغرام */
    measuredText: string | null;
    routeLabel: string | null;
    frequencyLabel: string | null;
    durationDays: number | null;
    speciesLabel: string | null;
    /** تحذيرات النشرة وفترة التحريم — تُذكر إن وُجدت ولا تُخترع */
    warnings: string[];
};
export type DraftSigResult = {
    ok: true;
    text: string;
} | {
    ok: false;
    reason: string;
};
export declare function draftSig(input: DraftSigInput): Promise<DraftSigResult>;
